window.kbPageData["views/entry/k-7f4e6b43f7f8ad05"] = {"key":"entry/k-7f4e6b43f7f8ad05","state":{"route":"entry/k-7f4e6b43f7f8ad05"},"node":{"id":"k-7f4e6b43f7f8ad05","mode":"k","title":"强军思想","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["新时代中国特色社会主义思想"],"资料类别":["非时政"]},"directorySummary":"习近平强军思想以“强军目标”为牵引，以“十一个明确”为主干，以“五个坚持”为\n精髓，涵盖新时代军队建设、改革和军事斗争准备各领域各方面，贯通军事力量建设和运用\n全过程，形成了一个内涵丰富、结构严谨、与时俱进的思想体系。\n1.“十一个明确”\n（1）明确党对人民军队的绝对领导是人民军队建军之本、强军之魂…","sources":[{"id":"fd51587340a36b0e","label":"强军思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"习近平强军思想以“强军目标”为牵引，以“十一个明确”为主干，以“五个坚持”为\n精髓，涵盖新时代军队建设、改革和军事斗争准备各领域各方面，贯通军事力量建设和运用\n全过程，形成了一个内涵丰富、结构严谨、与时俱进的思想体系。\n1.“十一个明确”\n（1）明确党对人民军队的绝对领导是人民军队建军之本、强军之魂。\n（2）明确强国必须强军，巩固国防和强大人民军队是新时代坚持和发展中国特色社会\n主义、实现中华民族伟大复兴的战略支撑，人民军队必须有效履行新时代使命任务。\n（3）明确党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军\n队，到 2027 年实现建军一百年奋斗目标，到 2035 年基本实现国防和军队现代化，到本世\n纪中叶把人民军队建成世界一流军队。\n（4）明确军队是要准备打仗的，必须聚焦能打仗、打胜仗。\n（5）明确推进强军事业必须坚持政治建军、改革强军、科技强军、人才强军、依法治\n军，坚持边斗争、边备战、边建设。\n（6）明确改革是强军的必由之路，必须推进军队组织形态现代化，构建中国特色现代\n军事力量体系，完善中国特色社会主义军事制度。\n（7）明确科技是核心战斗力，必须坚持自主创新战略基点，推进高水平科技自立自强。\n（8）明确强军之道要在得人，必须贯彻新时代军事教育方针。\n（9）明确依法治军是我们党建军治军基本方式。\n（10）明确军民融合发展是兴国之举、强军之策，必须巩固提高一体化国家战略体系\n和能力。\n（11）明确作风优良是我军鲜明特色和政治优势，必须全面从严治党、全面从严治军。\n2.五个坚持\n即：\n（1）坚持政治引领，\n（2）坚持以武止戈，\n（3）坚持积极进取，\n（4）坚持统筹兼顾，\n（5）坚持敢打必胜。\n3.新时代政治建军方略\n明确政治建军是人民军队立军之本，明确政治工作永远是我军的生命线，明确政治整训\n要突出政治上的正本清源，明确掌握思想领导是掌握一切领导的基础，明确党的力量来自组\n织、部队凝聚力战斗力来自组织，明确枪杆子要始终掌握在对党忠诚可靠的人手中，明确严\n才能正纲纪、严才能肃军威、严才能出战斗力，明确军中绝不能有腐败分子藏身之地，明确\n作风优良才能塑造英雄部队，明确军政军民团结是我军胜利法宝。","source":{"doc":"3ccc56f4000d1642c2d1","first":23,"last":24,"page":23,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-7f4e6b43f7f8ad05":[]}};
